import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
# find all "Demo pair N input (h x w):" and the FIRST subsequent occurrence with valid digits; take first occurrence per pair
def parse(t):
    G={}
    for m in re.finditer(r'Demo pair (\d+) (?:input|output) \((\d+)x(\d+)\):\n',t):
        k,h,w=m.group(1),int(m.group(2)),int(m.group(3))
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            v=[[int(x) for x in r] for r in rows]
            if k not in G:
                # dedup check: skip if this exact grid already parsed as same key from later occurrence? we need per-pair; use last occurrence per key to avoid old ones
                G[k]=v
    return G
G=parse(t)
print(sorted(G))
for k,v in G.items(): print(k,len(v),len(v[0]))

